def hydrate_time(nanoseconds, tz=None):
    """ Hydrator for `Time` and `LocalTime` values.

    :param nanoseconds:
    :param tz:
    :return: Time
    """

    if isinstance(nanoseconds, (int, float)):
        nanoseconds = int(nanoseconds)
    else:
        raise ValueError("`nanoseconds` must be an integer or a float value.")

    if not tz or tz == "Z":
        tz = pytz.UTC
    else:
        try:
            tz = pytz.timezone(tz)
        except pytz.UnknownTimeZoneError:
            raise ValueError(f"Unknown time zone: {tz}")

    return datetime.datetime.fromtimestamp(nanoseconds / NANOSECONDS_PER_SECOND, tz)

