    pty = subprocess.Popen(command_list, shell=True, bufsize=0, stdin=subprocess.PIPE, stdout=subprocess.PIPE, encoding='utf-8')

    if color:
        pty.start()
        return pty.communicate(timeout=None)
    else:
        # Get stdout from command
