        num_objects += 1

        # Validate the object
        if validate_objects:
            if obj.is_valid():
                good_objects += 1
            else:
                if show_warnings:
                    print(f"The object {obj} in the hierarchy is not valid.")

        # Check the digest of the object
        if check_digests:
            if not obj.validate_digest():
                if show_warnings:
                    print(f"The object {obj} in the hierarchy has an invalid digest.")

        # Add the object's children to the queue
        for child in obj.children:
            queue.append(child)

    return (num_objects, good_objects)

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Args:
        validate_objects (bool): Validate objects in the hierarchy
        check_digests (bool): Check object digests in the hierarchy
        show_warnings (bool): Show warnings during validation

    Returns:
        num_objects (int): Number of objects checked
        good_objects (int): Number of objects checked that were found to be valid
    """
    def check_digest(obj):
        return obj.digest is not None and obj.digest in obj.to_JSON()

    def validate_object(obj):
        if check_digests:
            if not check_digest(obj):
                return False
        if validate_objects:
            if not obj.validate():
                return False
        return True

    def traverse_hierarchy(parent):
        for child in parent.children:
            check_child = validate_object(child)
            if check_child:
                good_objects += 1
            num_objects += 1
            traverse_hierarchy(child)

    num_objects = 0
    good_objects = 0
    if show_warnings:
        warnings.warn("Validating storage root hierarchy...", RuntimeWarning)
    traverse_hierarchy(self)
    if show_warnings:
        warnings.warn(f"Finished validating storage root hierarchy. {good_objects} of {num_objects} objects were found to be valid.", RuntimeWarning)
    return num_objects, good_objects

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    # Get all objects in the storage root
    objects = self.storage_root.all_objects()

    # Validate objects if needed
    if validate_objects:
        objects = [obj for obj in objects if obj.is_valid()]

    # Validate digests if needed
    if check_digests:
        for obj in objects:
            if not obj.has_valid_digest(check_digests):
                if show_warnings:
                    print(f"WARNING: Digest for {obj} is invalid")

    # Count valid objects
    good_objects = len(objects)

    return objects, good_objects

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
        """Validate storage root hierarchy.

        Arguments:
            validate_objects (bool): Validate objects in the hierarchy (default: True)
            check_digests (bool): Check digests (default: True)
            show_warnings (bool): Show warnings (default: False)

        Returns:
            num_objects (int): Number of objects checked
            good_objects (int): Number of objects checked that were found to be valid
        """

        num_objects = 0
        good_objects = 0
        for obj in self.objects():
            num_objects += 1
            if validate_objects and not obj.validate():
                if show_warnings:
                    warnings.warn(f"Object {obj.id} is not valid.")
            else:
                good_objects += 1

        for layer in self.layers():
            for annotation in layer.annotations():
                if check_digests and not annotation.check_digest():
                    if show_warnings:
                        warnings.warn(f"Annotation {annotation.id} has invalid digest.")
                else:
                    good_objects += 1

        for annotation in self.orphan_annotations():
            if check_digests and not annotation.check_digest():
                if show_warnings:
                    warnings.warn(f"Annotation {annotation.id} has invalid digest.")
            else:
                good_objects += 1

        return num_objects, good_objects

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    num_objects = 0
    good_objects = 0

    for element in self.iter_elements():
        if validate_objects:
            try:
                element.validate(check_digests=check_digests, show_warnings=show_warnings)
            except Exception as e:
                if show_warnings:
                    warnings.warn("{}".format(e))

        num_objects += 1

        if element.validate(check_digests=check_digests, show_warnings=show_warnings):
            good_objects += 1

    return num_objects, good_objects

