def paging(response, max_results):
    """Returns WAPI response page by page."""
    result = []
    while len(result) + len(response) <= max_results:
        result.extend(response[:min(len(response), max_results - len(result))])
        response = response[min(len(response), max_results - len(result)):][1:]
        if response is None or len(response) == 0:
            break
    yield result

