            parse_errors.append(logging.LogRecord(config_filename, e.message, None, None, '', None, None))
    if overrides is not None:
        for override in overrides:
            if override.name in parsed_configs:
                values = parse_values(override.value, resolve_env)
                for attr, value in values.items():
                    parsed_configs[override.name][attr] = value
    return parsed_configs, parse_errors

def load_configurations(config_filenames, overrides=None, resolve_env=True):

    configs = {}
    parse_errors = []

    for config_filename in config_filenames:
        try:
            config = load_configuration(config_filename, overrides, resolve_env)
            configs[config_filename] = config
        except ValueError as e:
            parse_errors.append(logging.LogRecord(logging.ERROR, "Failed to load configuration file: {}".format(config_filename), e, traceback.format_exc()))

    return configs, parse_errors

