def scale(self, other=None, recompute=False):
    # Compute or set scale (integral of the histogram)
    if other is None and self._scale is not None and not recompute:
        # Return scale of this histogram
        return self._scale

    elif isinstance(other, float):
        # Rescale self to other
        if self._scale != 0.0:
            scale = other / self._scale
            if scale != 0.0:
                for key, value in self._histogram.items():
                    self._histogram[key] *= scale

        self._scale = other

