def scale(self, other=None, recompute=False):
        """Compute or set scale (integral of the histogram)."""

        if other is None:
            if not hasattr(self, "scale"):
                self.__calc_scale()
            return self.scale
        elif recompute or not hasattr(self, "scale"):
            if other <= 0:
                raise LenaValueError("Histograms with scale equal to zero can't be rescaled.")
            self.__calc_scale()
            self.scale = self.scale / other
            return self.scale
        else:
            if not hasattr(self, "scale"):
                self.__calc_scale()
            self.scale = self.scale * other
            return self.scale

    def __calc_scale(self):
        """Helper function to calculate scale (integral of the histogram)."""

        self.scale = 0
        for value, count in self.items():
            self.scale += value * count

