def hist_to_graph(hist, make_value=None, get_coordinate="left", field_names=("x", "y"), scale=None):
    if not make_value:
        make_value = lambda bin_: bin_.content
    if not field_names:
        field_names = (hist.name,)

    if get_coordinate == "left":
        coordinate = lambda bin_: bin_.left
    elif get_coordinate == "right":
        coordinate = lambda bin_: bin_.right
    elif get_coordinate == "middle":
        coordinate = lambda bin_: (bin_.left + bin_.right) / 2
    else:
        raise ValueError("Invalid get_coordinate argument")

    points = []
    for bin_ in hist.bins:
        point = [coordinate(bin_)]
        for name in field_names:
            if name in hist.names:
                point.append(make_value(getattr(bin_, name)))
            else:
                point.append(None)
        points.append(point)

    graph = Graph(points, labels=field_names)
    if scale is not None and scale is not False:
        graph.scale = scale if scale is True else hist.scale
    return graph

