def _verify(iface, candidate, tentative=False, vtype=None):
    """Verify that candidate might correctly provide iface."""
    try:

        ## Make sure the candidate claims that it provides the interface.
        if not tentative and not iface.providedBy(candidate):
            raise Invalid("candidate {candidate} does not provide {iface}")

        ## Make sure the candidate defines all required methods.
        for methname in iface.names(
                iface.BASES + (vtype,) if vtype else None):
            meth = getattr(candidate, methname)
            if meth is None:
                raise Invalid(
                    "candidate {candidate} does not define method {methname}")

        ## Make sure methods have the correct signature.
        for methname in iface.methods(
                iface.BASES + (vtype,) if vtype else None):
            sigf = iface.get(methname).signature()
            if sigf is not None:
                try:
                    sigf(vars(meth))
                except TypeError:
                    raise Invalid(
                        "candidate {candidate} has invalid signature for "
                        "method {methname}")

        ## Make sure the candidate defines all required attributes.
        for attrname in iface.names(
                iface.ATTRIBUTES, iface.BASES + (vtype,) if vtype else None):
            try:
                attr = getattr(candidate, attrname)
            except AttributeError:
                raise Invalid(
