def popitem(self):
    # Initialize a counter dictionary to keep track of the frequency of each unique value
    counter = {}

    # Iterate over the items in the dict and increment the frequency of the value for each key
    for key, value in self.items():
        if value in counter:
            counter[value] += 1
        else:
            counter[value] = 1

    # Find the least frequently used value and its corresponding key
    least_frequent_value = min(counter, key=counter.get)
    least_frequent_key = list(self.keys())[list(self.values()).index(least_frequent_value)]

    # Remove the least frequently used item from the dict and return it
    item = (least_frequent_key, least_frequent_value)
    del self[least_frequent_key]
